"""Minimal reader for Keynote .iwa files: snappy chunks, then protobuf archives.

Usage: python3 -I iwa.py <unzipped-key-dir> <command>
Commands: dump <file.iwa>   -- print every message with its type and decoded fields
"""
import sys, os, json


def varint(b, i):
    r = 0
    s = 0
    while True:
        c = b[i]
        i += 1
        r |= (c & 0x7F) << s
        s += 7
        if not c & 0x80:
            return r, i


def snappy_raw(b):
    n, i = varint(b, 0)
    out = bytearray()
    while i < len(b):
        tag = b[i]
        i += 1
        t = tag & 3
        if t == 0:
            ln = tag >> 2
            if ln >= 60:
                nb = ln - 59
                ln = int.from_bytes(b[i:i + nb], 'little')
                i += nb
            ln += 1
            out += b[i:i + ln]
            i += ln
        else:
            if t == 1:
                ln = ((tag >> 2) & 7) + 4
                off = ((tag >> 5) << 8) | b[i]
                i += 1
            elif t == 2:
                ln = (tag >> 2) + 1
                off = int.from_bytes(b[i:i + 2], 'little')
                i += 2
            else:
                ln = (tag >> 2) + 1
                off = int.from_bytes(b[i:i + 4], 'little')
                i += 4
            for _ in range(ln):
                out.append(out[-off])
    assert len(out) == n, (len(out), n)
    return bytes(out)


def iwa_decompress(data):
    i = 0
    out = bytearray()
    while i < len(data):
        assert data[i] == 0
        ln = int.from_bytes(data[i + 1:i + 4], 'little')
        out += snappy_raw(data[i + 4:i + 4 + ln])
        i += 4 + ln
    return bytes(out)


def pb_fields(b):
    """Decode one protobuf message into a list of (field, wiretype, value)."""
    i = 0
    res = []
    while i < len(b):
        key, i = varint(b, i)
        f, wt = key >> 3, key & 7
        if wt == 0:
            v, i = varint(b, i)
        elif wt == 1:
            v = b[i:i + 8]
            i += 8
        elif wt == 2:
            ln, i = varint(b, i)
            v = b[i:i + ln]
            i += ln
        elif wt == 5:
            v = b[i:i + 4]
            i += 4
        else:
            raise ValueError('wiretype %d' % wt)
        res.append((f, wt, v))
    if i != len(b):
        raise ValueError('overrun')
    return res


def try_msg(b):
    try:
        fs = pb_fields(b)
        if not fs:
            return None
        if any(f == 0 or f > 10000 for f, _, _ in fs):
            return None
        return fs
    except Exception:
        return None


def archives(data):
    """Yield (identifier, [(type, payload, object_refs, data_refs)])."""
    i = 0
    while i < len(data):
        ln, i = varint(data, i)
        ai = pb_fields(data[i:i + ln])
        i += ln
        ident = None
        infos = []
        for f, wt, v in ai:
            if f == 1:
                ident = v
            elif f == 2:
                mi = pb_fields(v)
                typ = None
                length = None
                orefs = []
                drefs = []
                for g, wt2, w in mi:
                    if g == 1:
                        typ = w
                    elif g == 3:
                        length = w
                    elif g == 5:
                        if wt2 == 2:
                            j = 0
                            while j < len(w):
                                x, j = varint(w, j)
                                orefs.append(x)
                        else:
                            orefs.append(w)
                    elif g == 6:
                        if wt2 == 2:
                            j = 0
                            while j < len(w):
                                x, j = varint(w, j)
                                drefs.append(x)
                        else:
                            drefs.append(w)
                infos.append([typ, length, orefs, drefs])
        msgs = []
        for typ, length, orefs, drefs in infos:
            msgs.append((typ, data[i:i + length], orefs, drefs))
            i += length
        yield ident, msgs


def load(path):
    with open(path, 'rb') as fh:
        return list(archives(iwa_decompress(fh.read())))


def show(b, depth=0, maxdepth=8):
    fs = try_msg(b)
    lines = []
    if fs is None:
        return None
    for f, wt, v in fs:
        pad = '  ' * depth
        if wt == 2:
            sub = try_msg(v) if depth < maxdepth else None
            try:
                s = v.decode('utf-8')
                printable = all(c.isprintable() or c in '\n\t  ￼' for c in s)
            except UnicodeDecodeError:
                printable = False
            if printable and (sub is None or len(s) > 0 and sum(c.isalpha() for c in s) > len(s) / 3):
                lines.append('%s%d: %r' % (pad, f, s))
            elif sub is not None:
                lines.append('%s%d: {' % (pad, f))
                lines.extend(show(v, depth + 1, maxdepth))
                lines.append('%s}' % pad)
            else:
                lines.append('%s%d: <%d bytes>' % (pad, f, len(v)))
        elif wt == 0:
            lines.append('%s%d: %d' % (pad, f, v))
        else:
            lines.append('%s%d: %s' % (pad, f, v.hex()))
    return lines


if __name__ == '__main__':
    root = sys.argv[1]
    cmd = sys.argv[2]
    if cmd == 'dump':
        for ident, msgs in load(os.path.join(root, sys.argv[3])):
            for typ, payload, orefs, drefs in msgs:
                print('== id %s type %s orefs %s drefs %s' % (ident, typ, orefs[:20], drefs))
                out = show(payload)
                if out:
                    print('\n'.join(out))

