"""Print every slide of an unzipped Keynote deck in show order: texts, owners, images."""
import sys, os
sys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))
import iwa

root = sys.argv[1]
idx = os.path.join(root, 'Index')

# data id -> file name
names = {}
for ident, msgs in iwa.load(os.path.join(idx, 'Metadata.iwa')):
    for typ, payload, orefs, drefs in msgs:
        if typ == 11006:
            for f, wt, v in iwa.pb_fields(payload):
                if f == 4:
                    d = dict((g, w) for g, _, w in iwa.pb_fields(v))
                    names[d[1]] = d[4].decode() if 4 in d else d[3].decode()

# slide order
doc = iwa.load(os.path.join(idx, 'Document.iwa'))
objs = {}
for ident, msgs in doc:
    objs[ident] = msgs
order = []
for ident, msgs in doc:
    for typ, payload, orefs, drefs in msgs:
        if typ == 2:
            for f, wt, v in iwa.pb_fields(payload):
                if f == 3:
                    for g, wt2, w in iwa.pb_fields(v):
                        if g == 2:
                            order.append(iwa.pb_fields(w)[0][2])
nodes = []
for nid in order:
    typ, payload, orefs, drefs = objs[nid][0]
    d = {}
    for f, wt, v in iwa.pb_fields(payload):
        d.setdefault(f, v)
    slide = iwa.pb_fields(d[2])[0][2]
    hidden = d.get(4, 0)
    thumb = names.get(drefs[0]) if drefs else None
    nodes.append((nid, slide, hidden, thumb))

files = {}
for fn in os.listdir(idx):
    if fn.startswith('Slide-'):
        files[int(fn[6:-4])] = fn

shown = 0
for n, (nid, slide, hidden, thumb) in enumerate(nodes, 1):
    if not hidden:
        shown += 1
    fn = files.get(slide)
    print('#' * 70)
    print('DECK %d  %s  %s  hidden=%s  thumb=%s' % (n, 'shown %d' % shown if not hidden else 'SKIPPED', fn, hidden, thumb))
    if fn is None:
        continue
    arch = iwa.load(os.path.join(idx, fn))
    owner = {}
    types = {}
    for ident, msgs in arch:
        types[ident] = msgs[0][0]
        for typ, payload, orefs, drefs in msgs:
            for r in orefs:
                owner.setdefault(r, []).append((ident, typ))
    allrefs = []
    for ident, msgs in arch:
        for typ, payload, orefs, drefs in msgs:
            allrefs.extend(drefs)
            if typ == 2001:
                text = None
                for f, wt, v in iwa.pb_fields(payload):
                    if f == 3:
                        text = v.decode('utf-8')
                if text and text.strip() and text.strip() != '￼':
                    print('  [text %s owner %s] %r' % (ident, owner.get(ident), text))
                elif text:
                    print('  [text %s owner %s] (object placeholder %r)' % (ident, owner.get(ident), text))
    imgs = [names.get(r, r) for r in allrefs]
    imgs = [i for i in imgs if not str(i).startswith('st-')]
    print('  images:', sorted(set(map(str, imgs))))
print('total nodes', len(nodes), 'shown', shown)

